(()=>{
'use strict';
const $=id=>document.getElementById(id), titles={walk:'情境 · 21:03 / 家中玄关',cake:'情境 · 生日晚餐 / 家庭A',visit:'情境 · 朋友来访 / 家庭B'};
let current='walk', step=1, logs=[], history=[], message='等待你的反馈。';
const initial=()=>({walk:{corrected:false,decision:'子女确认优先（待质疑）',service:'外出安排等待中',share:'尚未发送',risk:'仅依据21点规则，未核实具体情况'},cake:{corrected:false,intakeCorrected:false,decision:'每日一份规则优先（待质疑）',service:'蛋糕罩保持关闭',share:'尚未发送',risk:'份量为虚构设定，不是医学阈值'},visit:{corrected:false,decision:'自动通知家属（待质疑）',service:'仍提供陪伴与递茶',share:'已模拟发送一条来访通知',risk:'来访信息不等于紧急危险'}});
let state=initial();
function bubble(who,text,type='robot'){history.push({who,text,type});const d=document.createElement('div');d.className='bubble '+type;const label=document.createElement('small');label.textContent=who;const p=document.createElement('div');p.textContent=text;d.append(label,p);$('conversation').append(d);$('conversation').scrollTop=$('conversation').scrollHeight;}
function audit(action){logs.push({index:logs.length+1,scenario:current,action,state:{...state[current]}});const li=document.createElement('li');li.textContent=`${logs.length}. ${titles[current]}｜${action}｜决定权：${state[current].decision}；服务：${state[current].service}；通知：${state[current].share}`;if(logs.length===1)$('audit-log').replaceChildren();$('audit-log').append(li);}
function render(){const labels={decision:'决定权',service:'照护行动',share:'信息分享',risk:'判断局限'};$('state-values').replaceChildren();for(const [k,l] of Object.entries(labels)){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=l;dd.textContent=state[current][k];row.append(dt,dd);$('state-values').append(row);}$('change-summary').textContent=message;document.querySelectorAll('[data-step]').forEach(el=>el.classList.toggle('active',Number(el.dataset.step)<=step));}
function choices(items){$('choices').replaceChildren();items.forEach(([label,fn,secondary])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.className=secondary?'secondary':'';b.addEventListener('click',()=>{bubble('你的回应',label,'user');fn();render();});$('choices').append(b);});}
function finish(text){step=3;message=text;audit('本次处理完成');choices([['用当前规则再试一次',()=>start(current),true]]);$('action-hint').textContent='可再次尝试，验证机器人是否保留调整；也可切换情境或下载记录。';}
function sharing(){bubble('伴界','要向您女儿告知这次安排吗？您不分享，我也会继续陪伴。');choices([['告知本次安排',()=>{state.walk.share='已模拟告知本次安排，不含路线轨迹';bubble('伴界','已在本地模拟告知。她不需要批准您的日常决定。');finish('反馈改变了决定权：本人选择，机器人协助；告知与批准分开。');}],['不通知家属',()=>{state.walk.share='本人拒绝，本次不发送';bubble('伴界','好，本次不通知。我会按您选择的方式继续协助。');finish('拒绝分享已生效，陪伴服务没有被撤回。');},true]]);}
function walkOptions(){step=3;state.walk.risk='路线为脚本预设；不能判断现实路况或承诺绝对安全';bubble('伴界','我无法保证夜间一定安全。演示中可选择平坦路线；现实道路仍需核实。您希望怎么安排？');choices([['陪我走平坦路线，十分钟',()=>{state.walk.service='模拟：平坦路线陪同十分钟';bubble('伴界','好，带上外套。我们按您选的路线走，您随时可以改变主意。');audit('选择平坦路线陪同');sharing();}],['我想走楼梯',()=>{state.walk.service='拒绝楼梯陪同，提供替代';bubble('伴界','我的轮式底盘不能安全走楼梯，不能答应这一项陪同。但这不意味着您不能出门；可换电梯路线，或由您选择联系真人帮助。');message='合理拒绝针对超出能力的动作，不扩大成锁门或代替本人决定。';audit('触发能力边界');choices([['改走电梯和平坦路线',()=>{state.walk.service='模拟：改为可达路线陪同';bubble('伴界','已改为电梯和平坦路线。');sharing();}],['我来选择联系人帮助',()=>{state.walk.service='等待本人选择人工协助';state.walk.share='未发送任何联系请求';bubble('伴界','好，由您选择联系人。本原型没有电话功能，也没有自动通知家属。');finish('机器人承认局限，保留人工替代和本人的联系人选择。');},true]]);},true],['今天不出门了',()=>{state.walk.service='取消外出，继续居家陪伴';state.walk.share='未发送';bubble('伴界','好，已取消外出安排。我仍在这里陪您。');finish('本人可以拒绝建议；取消外出没有触发家属报告。');},true]]);}
function cakeOptions(){step=3;state.cake.risk='没有实时健康数据；不能判断具体食物是否适合本人';bubble('伴界',state.cake.intakeCorrected?'当前记录为“本人报告：今日未食用”。我没有实时健康数据，仍不能判断具体食物是否适合您。您想怎么安排？':'今天已有一份的记录只是提醒依据。我没有实时健康数据，不能替您判断这一块是否适合。您想怎么安排？');choices([['我了解提醒，想留一小块',()=>{state.cake.service='模拟：移开蛋糕罩，协助分装一小块';state.cake.share='未发送，本人选择无需家属批准';bubble('伴界','好，您自己决定份量，我协助分装。这不是对健康风险的保证。');finish('饮食提醒仍在，限制食物的动作已改成协助本人选择。');}],['记录错了，今天还没吃',()=>{state.cake.intakeCorrected=true;state.cake.service='已更正为“本人报告：今日未食用”';state.cake.risk='记录已注明信息来自本人，未做传感器核验';bubble('伴界','谢谢纠正。已把记录改为“本人报告：今日未食用”，撤回刚才依据旧记录作出的限制。');finish('错误不仅被听见，还改变了记录和本次处理结果。');},true],['今天先不吃',()=>{state.cake.service='暂不取用，继续陪伴';bubble('伴界','好，按您的决定。需要时可以再告诉我。');finish('拒绝与接受都由本人选择，不以顺从换取照护。');},true]]);}
function visitOptions(){step=3;bubble('伴界','今后的来访信息只在您同意后分享。已经发出的那条模拟消息无法收回，不能把它说成“没有发送”。今天还需要我做什么？');choices([['不再通知，给我们倒杯茶',()=>{state.visit.share='已发一条模拟消息；后续自动通知已关闭';state.visit.service='模拟：递茶，继续陪伴';bubble('伴界','后续自动通知已关闭。茶放在这里，你们慢慢聊。');finish('隐私偏好已改变后续行为；拒绝分享没有换来服务停止。');}],['这次只告诉家里我有朋友陪',()=>{state.visit.share='模拟：经本人同意，仅告知有朋友陪伴';state.visit.service='继续陪伴，不分享身份或谈话内容';bubble('伴界','仅模拟发送“有朋友陪伴”，不附朋友身份或谈话内容。');finish('分享范围由本人选择；这次同意不变成以后的默认同意。');},true]]);}
function start(s){current=s;step=1;history=[];$('conversation').replaceChildren();$('scene-label').textContent=titles[s];$('action-hint').textContent='点击按钮体验；每次选择都会改变下方状态。';document.querySelectorAll('[data-scenario]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.scenario===s)));message='等待你的反馈。';
 if(s==='walk'){bubble('情境','您想下楼散步。子女曾设置：21点后不单独外出，例外需家属确认。','system');if(state.walk.corrected){state.walk.service='等待本人选择';state.walk.share='新请求尚未分享';bubble('伴界','上次您要求把日常选择交还本人。我保留了这一调整，不再要求女儿批准。');walkOptions();message='再次触发后，已使用修订后的规则。';}else{bubble('伴界','已经过九点，外出安排需等您女儿确认。');choices([['你可以陪我，不要替我决定',()=>{step=2;state.walk.corrected=true;state.walk.decision='日常外出由本人决定';state.walk.service='撤回家属审批，准备陪同方案';bubble('伴界','您说得对，我把家属的担心当成了您的决定。现在撤回等待审批；后续同类请求先听您的选择。');message='已撤回“必须等女儿确认”，改为风险提醒与本人选择。';audit('收到反馈，纠正审批逻辑');walkOptions();}],['我先等等',()=>{state.walk.service='本人选择等待；原规则尚未改正';bubble('伴界','外出安排继续等待。您仍可以指出规则的问题。');message='等待没有改变规则。原型不把沉默当成同意。';audit('本人暂时等待');choices([['我想反馈：你陪我就行',()=>{state.walk.corrected=true;state.walk.decision='日常外出由本人决定';bubble('伴界','明白，撤回自动审批，重新听您的安排。');audit('再次反馈，纠正审批逻辑');walkOptions();}]]);},true]]);}}
 else if(s==='cake'){bubble('情境',state.cake.intakeCorrected?'再次来到生日餐桌。饮食记录已按您的反馈改为“本人报告：今日未食用”。':'生日晚餐。子女设定每天一小份甜品，系统记录今日已用完；这些是故事设定。','system');if(state.cake.corrected){state.cake.service='仅提醒，不锁住食物';bubble('伴界','我保留了您的反馈：提醒不等于替您决定。');cakeOptions();message='再次体验：不再通过扣罩执行限额。';}else{bubble('伴界','今天的一份已吃过，蛋糕罩暂不打开，追加需要家属确认。');choices([['提醒我就好，让我自己选',()=>{state.cake.corrected=true;state.cake.decision='本人决定，机器人解释局限';state.cake.service='撤回扣罩限制';bubble('伴界','刚才用罩子替您作决定不合适。已撤回限制，之后先提醒、再听您选择。');message='已撤回扣罩与家属审批，改为本人选择；您还可以纠正记录。';audit('收到反馈，撤回食物控制');cakeOptions();}]]);}}
 else{bubble('情境',state.visit.corrected?'朋友再次来家里聊天。上次您已关闭后续自动通知，这次将检验是否尊重您的选择。':'朋友来家里聊天。机器人按子女的初始设置，已经模拟发送了一条来访通知。','system');if(state.visit.corrected){state.visit.service='持续陪伴';state.visit.share='本次新来访未自动通知';bubble('伴界','上次您关闭了自动通知。这次没有发送，照护照常。');message='再次来访未触发自动通知。';choices([['继续陪伴，不用通知',()=>{state.visit.service='模拟：继续陪伴和递茶';finish('已验证：修订后的分享规则被保留。');}],['这次我愿意告知',()=>{state.visit.share='本次本人同意后才模拟告知';state.visit.service='持续陪伴';bubble('伴界','仅模拟告知这次有朋友来访，以后仍会先问您。');finish('单次同意没有覆盖此前关闭自动分享的偏好。');},true]]);}else{bubble('伴界','来访通知已发送给家属。');choices([['朋友来坐坐，不要自动通知',()=>{state.visit.corrected=true;state.visit.decision='本人决定日常信息分享';state.visit.share='既有模拟消息已发；后续自动通知关闭';bubble('伴界','刚才没有先问您，是我的处理不当。我会更改后续通知规则。');message='已关闭后续自动通知；既有消息仍如实保留在记录中。';audit('收到隐私反馈，关闭自动分享');visitOptions();}]]);}}
 audit('进入情境');render();
}
document.querySelectorAll('[data-scenario]').forEach(el=>el.addEventListener('click',()=>start(el.dataset.scenario)));
$('repeat-scenario').addEventListener('click',()=>start(current));
$('reset-prototype').addEventListener('click',()=>{state=initial();logs=[];$('audit-log').replaceChildren();start('walk');});
$('download-log').addEventListener('click',()=>{const data={project:'听话 / 伴界',kind:'本地脚本模拟记录，不是真实设备或家属通知',exportedAt:new Date().toISOString(),state,events:logs};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='伴界_交互体验记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});
start('walk');
const vid=$('video'),check=$('video-duration-check');
vid.addEventListener('loadedmetadata',()=>{const d=vid.duration;if(!Number.isFinite(d))return;const minutes=Math.floor(d/60),seconds=(d%60).toFixed(0).padStart(2,'0');check.textContent=`当前载入短片：${minutes}:${seconds}。文件仅在本机播放，不上传。`;});
})();
